  "space": {"2": "8px", "4": "16px"},
  "radius": {"md": "10px"}
}""")
def ratakan(d, awal=""):
    for k, v in d.items():
        nama = f"{awal}-{k}" if awal else k
        yield from ratakan(v, nama) if isinstance(v, dict) else [(nama, v)]
def css_nilai(v):
    return f"var(--{v[1:-1].replace('.', '-')})" if v.startswith("{") else v
print(":root {")
for nama, v in ratakan(token):
    print(f"  --{nama}: {css_nilai(v)};")
print("}")

